# simulation/action_result.py


class ActionResult:

    def __init__(
        self,
        event=None,
        message="",
        data=None
    ):

        # Event generated by the action.
        self.event = event

        # Human-readable description.
        self.message = message

        # Optional additional information.
        self.data = (
            data
            if data is not None
            else {}
        )

    def __str__(self):

        return self.message